BEGIN
  IF NEW.parent_project_id IS DISTINCT FROM OLD.parent_project_id THEN
    IF NEW.parent_project_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM container_closure WHERE ancestor_id=NEW.id AND descendant_id=NEW.parent_project_id) THEN
      RAISE EXCEPTION 'container reparent would create a cycle (% -> %)', NEW.id, NEW.parent_project_id;
    END IF;
    DELETE FROM container_closure
      WHERE descendant_id IN (SELECT descendant_id FROM container_closure WHERE ancestor_id=NEW.id)
        AND ancestor_id IN (SELECT ancestor_id FROM container_closure WHERE descendant_id=NEW.id AND ancestor_id<>NEW.id);
    IF NEW.parent_project_id IS NOT NULL THEN
      INSERT INTO container_closure(ancestor_id,descendant_id,depth)
        SELECT sup.ancestor_id, sub.descendant_id, sup.depth+sub.depth+1
          FROM container_closure sup, container_closure sub
         WHERE sup.descendant_id=NEW.parent_project_id AND sub.ancestor_id=NEW.id;
    END IF;
  END IF;
  RETURN NEW;
END

